package dev.slithergoh.pixelmonradar.client.screen;

import dev.slithergoh.pixelmonradar.client.OreScanner;import dev.slithergoh.pixelmonradar.client.RadarSettings;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.client.gui.components.Button;import net.minecraft.client.gui.components.EditBox;import net.minecraft.client.gui.screens.Screen;import net.minecraft.network.chat.Component;import net.minecraft.resources.ResourceLocation;import java.util.List;
public final class OreScreen extends Screen{private EditBox search;private List<ResourceLocation>ores=List.of();private int scroll;public OreScreen(){super(Component.literal("Ore Scanner"));}@Override protected void init(){int l=width/2-210;ores=OreScanner.candidates();search=new EditBox(font,l,40,250,20,Component.literal("Search blocks"));search.setHint(Component.literal("Search vanilla / Pixelmon / modded ores..."));addRenderableWidget(search);addRenderableWidget(Button.builder(Component.literal("ESP: "+on(RadarSettings.oreEspEnabled)),b->{RadarSettings.oreEspEnabled=!RadarSettings.oreEspEnabled;b.setMessage(Component.literal("ESP: "+on(RadarSettings.oreEspEnabled)));RadarSettings.save();}).bounds(l+255,40,75,20).build());addRenderableWidget(Button.builder(Component.literal("Range: "+RadarSettings.oreRange),b->{RadarSettings.oreRange=RadarSettings.oreRange>=64?8:RadarSettings.oreRange+8;b.setMessage(Component.literal("Range: "+RadarSettings.oreRange));RadarSettings.save();}).bounds(l+335,40,85,20).build());addRenderableWidget(Button.builder(Component.literal("Clear selected"),b->{RadarSettings.selectedOres.clear();RadarSettings.save();}).bounds(l,65,130,20).build());}private static String on(boolean v){return v?"ON":"OFF";}private List<ResourceLocation>f(){String q=search==null?"":search.getValue().toLowerCase();return ores.stream().filter(x->x.toString().toLowerCase().contains(q)).toList();}@Override public void render(GuiGraphics g,int mx,int my,float pt){renderBackground(g,mx,my,pt);int l=width/2-210;g.fill(l-8,16,l+428,height-20,0xC0101016);g.drawCenteredString(font,title,width/2,22,0xFFFFFF);super.render(g,mx,my,pt);List<ResourceLocation>a=f();int max=Math.max(1,(height-120)/18);scroll=Math.min(scroll,Math.max(0,a.size()-max));int y=96;for(int i=scroll;i<a.size()&&i<scroll+max;i++){ResourceLocation id=a.get(i);boolean s=RadarSettings.selectedOres.contains(id.toString());g.fill(l,y-2,l+420,y+14,s?0x80508050:0x50303038);g.drawString(font,(s?"[x] ":"[ ] ")+id,l+5,y+1,s?0x80FF80:0xFFFFFF,false);y+=18;}g.drawString(font,RadarSettings.selectedOres.size()+" selected | "+a.size()+" matching registry blocks | wheel to scroll",l,height-16,0xAAAAAA,false);}@Override public boolean mouseClicked(double mx,double my,int b){int l=width/2-210;List<ResourceLocation>a=f();int max=Math.max(1,(height-120)/18),y=96;if(mx>=l&&mx<=l+420)for(int i=scroll;i<a.size()&&i<scroll+max;i++,y+=18)if(my>=y-2&&my<=y+14){String id=a.get(i).toString();if(!RadarSettings.selectedOres.remove(id))RadarSettings.selectedOres.add(id);RadarSettings.save();return true;}return super.mouseClicked(mx,my,b);}@Override public boolean mouseScrolled(double mx,double my,double sx,double sy){List<ResourceLocation>a=f();int max=Math.max(1,(height-120)/18);scroll=Math.max(0,Math.min(Math.max(0,a.size()-max),scroll+(sy<0?1:-1)));return true;}@Override public void onClose(){RadarSettings.save();super.onClose();}@Override public boolean isPauseScreen(){return false;}}
